```go
package main

import "fmt"

func newCounter() func() int {
    count := 0
    return func() int {
        count++
        return count
    }
}

func main() {
    first := newCounter()
    second := newCounter()
    fmt.Println(first(), first(), second())
}
```
The output is `1 2 1`. The first two calls share one captured `count`; the final call uses a different factory invocation and a different variable.

```go
package main

import "fmt"

func logger(prefix string) func(string) {
    return func(message string) {
        fmt.Printf("[%s] %s\n", prefix, message)
    }
}

func main() {
    apiLog := logger("api")
    apiLog("started")
    apiLog("ready")
}
```
The closure binds `api` once, while each call supplies only the new message. The two output lines start with `[api]`.

```go
package main

import "fmt"

func bind(value string) func() string {
    return func() string { return value }
}

func main() {
    items := []string{"red", "green", "blue"}
    var current string
    var shared, copied []func() string
    for _, item := range items {
        current = item
        shared = append(shared, func() string { return current })
        copied = append(copied, bind(item))
    }
    fmt.Println(shared[0](), copied[0]())
}
```
The output is `blue red`. `shared[0]` reads the reused outer variable, while `bind` creates a new parameter variable for the first value.

```go
package main

import "fmt"

func counter() func() int {
    n := 0
    return func() int { n++; return n }
}

type Counter struct{ n int }
func (c *Counter) Next() int { c.n++; return c.n }
func (c *Counter) Reset()    { c.n = 0 }

func main() {
    next := counter()
    fmt.Println(next(), next())
    var c Counter
    fmt.Println(c.Next())
    c.Reset()
}
```
The closure is compact for `Next` alone. The struct becomes clearer as soon as `Reset` and other operations join the same state.

