```go
package main

import (
    "fmt"
    "sync"
)

func counter() func() int {
    var mu sync.Mutex
    count := 0
    return func() int {
        mu.Lock()
        defer mu.Unlock()
        count++
        return count
    }
}

func main() {
    next := counter()
    var wg sync.WaitGroup
    for range 3 {
        wg.Add(1)
        go func() { defer wg.Done(); next() }()
    }
    wg.Wait()
    fmt.Println(next())
}
```
After three concurrent increments, the final call prints `4`. The mutex serializes the complete increment and read operation.
